/* Norwegian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ole": "ancestor's descendant — Old Norse Olaf", "Ingrid": "Ing's beauty — Old Norse Ing + fridr", "Lars": "crowned with laurel — Latin Laurentius", "Kari": "pure — Greek Katherine", "Knut": "knot — Old Norse knutr", "Astrid": "god-beautiful — Old Norse ass (god) + fridr", "Hansen": "The most common Norwegian surname.", "Johansen": "Among the most common surnames.", "Olsen": "A classic -sen surname.", "Larsen": "A classic -sen surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ole';
console.log(lookup(q));

